export const STEREOTYPES=['block','interfaceBlock','constraintBlock','requirement','testCase','valueType','system','subsystem','hardware','software','human','sensor','actuator','safetyCritical','machine','cnc','robot','cobot','inspection','manufacturingResource'];
export function normalizeEngineering(m){m.library??=[];for(const n of m.nodes){n.stereotypes??=[];n.ports??=[];n.properties??=[];n.behavior??='';n.moflt??='';}return m}
export function expandedNeeds(m,op){const needs=new Map();const add=(id,q)=>needs.set(id,(needs.get(id)||0)+q);for(const e of m.edges.filter(e=>e.type==='requires'&&e.from===op.id)){add(e.to,e.quantity);for(const staffing of m.edges.filter(s=>s.type==='staffedBy'&&s.from===e.to))add(staffing.to,e.quantity*staffing.quantity)}return needs}
export function validateEngineering(m){
 const byId=new Map(m.nodes.map(n=>[n.id,n]));const portIds=new Set();
 if(m.library&&!Array.isArray(m.library))throw Error('Bibliotecă invalidă.');
 if((m.library?.length||0)>200)throw Error('Maximum 200 șabloane personale.');
 const templates=new Set();for(const t of m.library||[]){if(!t||typeof t.id!=='string'||!t.id||templates.has(t.id)||typeof t.name!=='string'||!t.element||!Array.isArray(t.element.ports)||!Array.isArray(t.element.attributes)||!t.element.params||!t.element.bindings)throw Error('Șablon personal invalid.');templates.add(t.id);}
 for(const n of m.nodes){if(n.stereotypes&&(!Array.isArray(n.stereotypes)||n.stereotypes.some(s=>typeof s!=='string'||s.length>100)))throw Error('Stereotip invalid.');if(n.ports&&!Array.isArray(n.ports))throw Error('Porturi invalide.');if((n.ports?.length||0)>8)throw Error('Maximum 8 porturi per element în această versiune.');for(const p of n.ports||[]){if(!p.id||portIds.has(p.id)||typeof p.name!=='string'||!['in','out','inout'].includes(p.direction)||!['proxy','full','standard'].includes(p.kind)||typeof p.payload!=='string')throw Error('Port invalid sau ID duplicat.');portIds.add(p.id);if(p.typeRef&&!['interfaceBlock','interface'].includes(byId.get(p.typeRef)?.type))throw Error('Tipul portului trebuie să fie Interface block / Interface.');}if(n.properties&&(!Array.isArray(n.properties)||n.properties.some(p=>typeof p.name!=='string'||typeof p.value!=='string'||typeof p.type!=='string')))throw Error('Proprietate MBSE invalidă.');}
 for(const e of m.edges){const a=byId.get(e.from),b=byId.get(e.to);if(!a||!b)continue;
 if(e.type==='staffedBy'&&(!['machine','robot','hardware','tool'].includes(a.type)||!['person','team'].includes(b.type)||!Number.isInteger(e.quantity)||e.quantity<1))throw Error('Operator per mașină: mașină/robot/HW/dispozitiv → operator/echipă, cantitate întreagă.');
 if(e.fromPort||e.toPort){const p=a.ports?.find(p=>p.id===e.fromPort),q=b.ports?.find(p=>p.id===e.toPort);if(!p||!q)throw Error('Conectorul referențiază un port lipsă.');if(!['connector','assemblyConnector','delegation','itemFlow','binding'].includes(e.type))throw Error('Acest tip de relație nu conectează porturi.');if(e.type!=='binding'&&(p.direction==='in'||q.direction==='out'))throw Error('Direcție port incompatibilă: out/inout → in/inout.');if(p.payload&&q.payload&&p.payload!==q.payload)throw Error('Tipuri de flux incompatibile între porturi.');if(p.typeRef&&q.typeRef&&p.typeRef!==q.typeRef)throw Error('Interfețe diferite între porturi.');}
 if(e.type==='verify'&&(!['testCase','inspection'].includes(a.type)||b.type!=='requirement'))throw Error('«verify»: testCase/inspecție → cerință.');if(['deriveReqt','copy'].includes(e.type)&&(a.type!=='requirement'||b.type!=='requirement'))throw Error('Relația cere două cerințe.');if(['include','extend'].includes(e.type)&&(a.type!=='useCase'||b.type!=='useCase'))throw Error('include/extend conectează două use case-uri.');if(e.type==='transition'&&(!['state','initial','final','decision'].includes(a.type)||!['state','initial','final','decision'].includes(b.type)))throw Error('Tranziția conectează noduri de stare.');if(e.type==='message'&&(!Number.isFinite(e.order)||e.order<1))throw Error('Mesajul are nevoie de o ordine pozitivă.');
 }
}
export function modelAudit(m){const findings=[];for(const r of m.nodes.filter(n=>n.type==='requirement')){if(!m.edges.some(e=>e.type==='satisfies'&&e.to===r.id))findings.push({id:r.id,text:'Cerință fără satisfiere: '+r.name});if(!m.edges.some(e=>e.type==='verify'&&e.to===r.id))findings.push({id:r.id,text:'Cerință fără verificare: '+r.name});}for(const n of m.nodes)for(const p of n.ports||[])if(!m.edges.some(e=>e.fromPort===p.id||e.toPort===p.id))findings.push({id:n.id,text:'Port neconectat: '+n.name+'.'+p.name});return findings}
